<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { reportProvider } from '@/services/report'
import { ApiError } from '@/services/api'
import { useAuthStore } from '@/stores/auth'
import type { SurveyPeriod, CreatePeriod } from '@/types/report'
import { beijingInput, beijingUtc, validatePeriod, windowLabels } from '@/utils/report'
import { formatBeijingTime } from '@/utils/filing'
const auth=useAuthStore();const rows=ref<SurveyPeriod[]>([]);const busy=ref(false);const visible=ref(false);const editing=ref<SurveyPeriod|null>(null);const errors=ref<Record<string,string>>({})
const labels={startAt:'调查开始（含）',endExclusiveAt:'调查结束（不含）',openAt:'填报开放（含）',closeAt:'填报截止（不含）'}
const form=reactive({code:'',label:'',startAt:'',endExclusiveAt:'',openAt:'',closeAt:'',demo:true})
async function load(){busy.value=true;try{rows.value=(await reportProvider.periods(auth.token!)).data.items}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
function edit(p:SurveyPeriod|null){editing.value=p;errors.value={};Object.assign(form,{code:p?.code??'',label:p?.label??'',demo:p?.demo??true});for(const k of Object.keys(labels) as (keyof typeof labels)[])form[k]=beijingInput(p?.[k]??null);visible.value=true}
async function save(){errors.value={};let body:CreatePeriod;try{body={...form,label:form.label.trim(),startAt:beijingUtc(form.startAt),endExclusiveAt:beijingUtc(form.endExclusiveAt),openAt:beijingUtc(form.openAt),closeAt:beijingUtc(form.closeAt)}}catch{ElMessage.error('请完整选择四个北京时间');return}errors.value=validatePeriod(body);if(Object.keys(errors.value).length)return;busy.value=true;try{if(editing.value){const {code,demo,...fields}=body;await reportProvider.update(code,{...fields,expectedVersion:editing.value.currentVersion},auth.token!)}else await reportProvider.create(body,auth.token!);visible.value=false;ElMessage.success('调查期已保存');await load()}catch(e){if(e instanceof ApiError){errors.value=e.fieldErrors;if(e.status===409)await load()}ElMessage.error((e as Error).message)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><h1>调查期管理</h1><p>时间按北京时间显示，调查范围和填报窗口均为前含后不含。</p></div><el-button type="primary" @click="edit(null)">新增调查期</el-button><el-button @click="load">刷新</el-button></div><el-table v-loading="busy" :data="rows" empty-text="暂无调查期"><el-table-column prop="code" label="代码" min-width="150"/><el-table-column prop="label" label="名称" min-width="180"/><el-table-column label="调查范围" min-width="220"><template #default="s">{{formatBeijingTime(s.row.startAt)}} 至 {{formatBeijingTime(s.row.endExclusiveAt)}}</template></el-table-column><el-table-column label="填报窗口" min-width="220"><template #default="s">{{formatBeijingTime(s.row.openAt)}} 至 {{formatBeijingTime(s.row.closeAt)}}</template></el-table-column><el-table-column label="状态" width="160"><template #default="s">{{windowLabels[s.row.windowStatus as keyof typeof windowLabels]}} {{s.row.demo?' · 演示':''}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="s"><el-button :disabled="s.row.legacy||s.row.windowStatus!=='NOT_OPEN'" @click="edit(s.row)">修改</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="editing?'修改调查期':'新增调查期'" width="min(600px,94vw)"><el-form label-position="top"><el-form-item label="期次代码" :error="errors.code" required><el-input v-model="form.code" :disabled="!!editing" maxlength="32"/></el-form-item><el-form-item label="名称" :error="errors.label" required><el-input v-model="form.label" maxlength="80"/></el-form-item><el-form-item v-for="(label,key) in labels" :key="key" :label="label+'（北京时间）'" :error="errors[key]" required><el-date-picker v-model="form[key]" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item><el-checkbox v-model="form.demo" :disabled="!!editing">匿名演示调查期</el-checkbox></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></section></template>
